// Verifica la firma HMAC de la tienda (contrato, apartado 3):
// sha256=HMAC(secreto, timestamp + "." + cuerpo_exacto), con 5 minutos de margen.
const crypto = require('crypto');

const item = $input.first();
const headers = item.json.headers;
const secret = $env.PIQUANTUM_WEBHOOK_SECRET || '';

// El cuerpo EXACTO que llegó (Raw Body). Si se usara item.json.body, n8n lo habría
// vuelto a serializar y la firma ya no coincidiría.
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');

const timestamp = headers['x-piquantum-timestamp'] || '';
const received = headers['x-piquantum-signature'] || '';
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + raw).digest('hex');

// Comparación en tiempo constante (como hash_equals en PHP)
const signatureOk = received.length === expected.length
  && crypto.timingSafeEqual(Buffer.from(received), Buffer.from(expected));
const age = Math.abs(Date.now() / 1000 - Number(timestamp));
const timeOk = Number.isFinite(age) && age <= 300;

let reason = null;
if (!secret) reason = 'n8n sin PIQUANTUM_WEBHOOK_SECRET';
else if (!signatureOk) reason = 'firma incorrecta';
else if (!timeOk) reason = 'timestamp fuera de la ventana de 5 minutos';

let event = null;
try { event = JSON.parse(raw); } catch (e) { reason = reason || 'cuerpo que no es JSON'; }

return [{ json: { valid: reason === null, reason, event } }];

// Validación de los eventos de pedido (contrato, apartados 4 a 6). Devuelve la lista de errores.
const ev = $input.first().json.event;
const d = ev.data || {};
const o = d.order || {};
const c = d.customer || {};
const a = d.shipping_address || {};
const lines = Array.isArray(d.lines) ? d.lines : [];
const errors = [];

const isNum = v => typeof v === 'number' && Number.isFinite(v);
const filled = v => typeof v === 'string' && v.trim() !== '';
const near = (x, y) => Math.abs(x - y) <= 0.01;
const money = v => v.toFixed(2);
const STATUSES = ['creado', 'pagado_simulado', 'pendiente_preparacion', 'enviado', 'cancelado', 'incidencia'];

// Sobre
if (!filled(ev.event_id)) errors.push('event_id: obligatorio');
if (!filled(ev.occurred_at) || isNaN(Date.parse(ev.occurred_at))) errors.push('occurred_at: fecha ISO 8601 obligatoria');
if (ev.source !== 'piquantum-web') errors.push('source: debe ser piquantum-web');

// Pedido
if (!/^PQ-\d{8}-[A-Z0-9]{6}$/.test(o.reference || '')) errors.push('data.order.reference: formato PQ-AAAAMMDD-XXXXXX');
if (!STATUSES.includes(o.status)) errors.push('data.order.status: estado desconocido');
if (ev.type === 'order.created' && o.status !== 'creado') errors.push('data.order.status: en order.created debe ser creado');
for (const k of ['subtotal', 'discount', 'shipping', 'total']) {
  if (!isNum(o[k])) errors.push(`data.order.${k}: número obligatorio`);
}
if (isNum(o.discount) && o.discount < 0) errors.push('data.order.discount: debe ser ≥ 0');
if (isNum(o.shipping) && o.shipping < 0) errors.push('data.order.shipping: debe ser ≥ 0');
if (filled(o.discount_code) && !(o.discount > 0)) errors.push('data.order.discount: obligatorio si hay discount_code');

// Cliente y dirección
if (!filled(c.name)) errors.push('data.customer.name: obligatorio');
if (!filled(c.email)) errors.push('data.customer.email: obligatorio');
else if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(c.email)) errors.push('data.customer.email: formato no válido');
for (const k of ['name', 'address', 'city', 'country']) {
  if (!filled(a[k])) errors.push(`data.shipping_address.${k}: obligatorio`);
}
if (!/^\d{5}$/.test(a.postal_code || '')) errors.push('data.shipping_address.postal_code: 5 dígitos');

// Líneas
if (lines.length === 0) errors.push('data.lines: al menos 1 línea');
lines.forEach((l, i) => {
  const p = `data.lines[${i}]`;
  if (!filled(l.product_code)) errors.push(`${p}.product_code: obligatorio`);
  if (!Number.isInteger(l.quantity) || l.quantity < 1) errors.push(`${p}.quantity: debe ser ≥ 1`);
  if (!isNum(l.unit_price) || l.unit_price <= 0) errors.push(`${p}.unit_price: debe ser > 0`);
  if (!isNum(l.line_total) || !isNum(l.quantity) || !isNum(l.unit_price) || !near(l.quantity * l.unit_price, l.line_total)) {
    errors.push(`${p}.line_total: no coincide con quantity × unit_price`);
  }
});

// Totales
const sumLines = lines.reduce((s, l) => s + (isNum(l.line_total) ? l.line_total : 0), 0);
if (isNum(o.subtotal) && !near(sumLines, o.subtotal)) {
  errors.push(`data.order.subtotal: ${money(o.subtotal)} no coincide con la suma de las líneas (${money(sumLines)})`);
}
if ([o.subtotal, o.discount, o.shipping, o.total].every(isNum)) {
  const expected = Math.round((o.subtotal - o.discount + o.shipping) * 100) / 100;
  if (!near(expected, o.total) || o.total <= 0) {
    errors.push(`data.order.total: ${money(o.total)} no coincide con subtotal − discount + shipping (${money(expected)})`);
  }
}

// Bloques propios de cada tipo
if (ev.type === 'payment.simulated') {
  const pay = d.payment || {};
  if (pay.method !== 'redsys') errors.push('data.payment.method: solo redsys');
  if (!['approved', 'declined'].includes(pay.status)) errors.push('data.payment.status: approved o declined');
  if (pay.status === 'approved' && !(isNum(pay.amount) && isNum(o.total) && near(pay.amount, o.total))) {
    errors.push('data.payment.amount: con approved debe ser igual a order.total');
  }
}
if (ev.type === 'order.status_changed') {
  const ch = d.change || {};
  if (ch.status !== o.status) errors.push('data.change.status: debe coincidir con data.order.status');
  if (ch.origin !== 'backoffice') errors.push('data.change.origin: solo se integran los cambios del panel de la tienda');
}

return [{ json: { valid: errors.length === 0, errors, event: ev } }];

// Tienda → formato de POST /api/v1/webhooks/orders del back-office (contrato, apartado 9)
const ev = $input.first().json.event;
const d = ev.data;
const o = d.order;
const a = d.shipping_address;

const payload = {
  event_id: ev.event_id,                       // idempotencia del back-office («duplicate»)
  execution_id: 'n8n_' + $execution.id,        // trazabilidad: ejecución de n8n en el log del back-office
  event_type: ev.type,
  occurred_at: ev.occurred_at,
  order_ref: o.reference,
  status: o.status,                            // tal cual: el back-office acepta los estados de la tienda
  payment_method: 'redsys_sandbox',
  shipping_address: `${a.address}, ${a.postal_code} ${a.city} (${a.country})`,
  customer: { name: d.customer.name, email: d.customer.email },
  items: d.lines.map(l => ({
    sku: l.product_code,                       // el product_code de la tienda es el sku del almacén
    product_name: l.name,
    variant_size: l.size,
    quantity: l.quantity,
    unit_price: l.unit_price,
  })),
  discount_code: o.discount_code,
  discount_amount: o.discount,
  shipping_amount: o.shipping,
  total_amount: o.total,
};

return [{ json: { event_id: ev.event_id, payload } }];
